style.css:
@-moz-document url-prefix("https://www.google.") {
/* 搜索结果页顶部搜索框：靠左 */
  #searchform {
  display: flex !important;
  justify-content: flex-start !important;
  width: 100% !important;
}

  /* 首页搜索框：靠左 */
  form[role="search"] {
    margin-left: 0 !important;
    margin-right: auto !important;
  }
}
